"""Generate the temporary Scientific Victory Advance-count scanner."""

import sys
import argparse
import re
from pathlib import Path

if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")

REPO_ROOT = Path(__file__).resolve().parents[4]
ADVANCES_DIR = REPO_ROOT / "reference_game_files" / "game" / "in_game" / "common" / "advances"
OUT_FILE = REPO_ROOT / "src" / "in_game" / "common" / "scripted_effects" / "tv_science_score_effects.txt"

HEADER = """\
# @Generated by scripts/in_game/common/scripted_effects/gen_tv_science_score_effects.py
#   Data:    reference_game_files/game/in_game/common/advances/*.txt
#   Regen:   conda run --no-capture-output -n eu5 python scripts/in_game/common/scripted_effects/gen_tv_science_score_effects.py
# Do not edit directly - update the mirrored Advance definitions and re-run the generator.
"""


def strip_script_comment(line: str) -> str:
    """Strip a Jomini # comment while preserving # inside quoted strings."""
    in_string = False
    escaped = False
    chars: list[str] = []
    for char in line:
        if escaped:
            chars.append(char)
            escaped = False
            continue
        if char == "\\" and in_string:
            chars.append(char)
            escaped = True
            continue
        if char == '"':
            in_string = not in_string
            chars.append(char)
            continue
        if char == "#" and not in_string:
            break
        chars.append(char)
    return "".join(chars)


def brace_delta(text: str) -> int:
    """Count structural braces outside quoted strings."""
    in_string = False
    escaped = False
    delta = 0
    for char in text:
        if escaped:
            escaped = False
            continue
        if char == "\\" and in_string:
            escaped = True
            continue
        if char == '"':
            in_string = not in_string
        elif not in_string:
            if char == "{":
                delta += 1
            elif char == "}":
                delta -= 1
    return delta


def load_all_advance_ids() -> list[str]:
    """Read every top-level Advance id from the mirrored vanilla definitions."""
    definition_re = re.compile(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*\{")
    advance_ids: set[str] = set()
    files = sorted(ADVANCES_DIR.glob("*.txt"))
    if not files:
        raise FileNotFoundError(f"No Advance definitions found under {ADVANCES_DIR}")

    for path in files:
        depth = 0
        for line_number, raw_line in enumerate(path.read_text(encoding="utf-8-sig").splitlines(), start=1):
            line = strip_script_comment(raw_line)
            if depth == 0:
                match = definition_re.match(line)
                if match:
                    advance_ids.add(match.group(1))
            depth += brace_delta(line)
            if depth < 0:
                raise ValueError(f"Unbalanced closing brace in {path}:{line_number}")
        if depth != 0:
            raise ValueError(f"Unbalanced braces in {path}")

    if not advance_ids:
        raise ValueError(f"Advance definition scan found no ids under {ADVANCES_DIR}")
    return sorted(advance_ids)


def generate() -> str:
    advance_ids = load_all_advance_ids()
    lines = [
        HEADER.rstrip(),
        "",
        "# TEMPORARY ENGINE WORKAROUND: the engine num_advance_researched interface",
        "# (exposed to script as num_of_advances_researched) is broken/stuck in the",
        "# affected EU5 build. Player countries rebuild this score with a yearly full",
        "# has_advance scan until Paradox fixes the interface; then remove this file.",
        f"# Generated from {len(advance_ids)} top-level definitions in reference_game_files/game/in_game/common/advances/.",
        "",
        "tv_update_science_score_effect = {",
        "\tset_variable = { name = tv_science_score value = 0 }",
    ]
    for advance_id in advance_ids:
        lines.extend([
            "\tif = {",
            f"\t\tlimit = {{ has_advance = {advance_id} }}",
            "\t\tchange_variable = { name = tv_science_score add = 1 }",
            "\t}",
        ])
    lines.extend(["}", ""])
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--dry", action="store_true", help="Print output instead of writing it")
    args = parser.parse_args()
    content = generate()
    if args.dry:
        print(content)
        return
    OUT_FILE.parent.mkdir(parents=True, exist_ok=True)
    OUT_FILE.write_text(content, encoding="utf-8-sig")
    print(f"Wrote {OUT_FILE.relative_to(REPO_ROOT)}")


if __name__ == "__main__":
    main()
